#!/bin/bash
# launch-codex.sh <ID> <prompt> — Codex worker pane on gpt-6-sol (default worker since 2026-09-23 evening). The suffix carries the write-scope and stop-rule clarifications Codex needs.
ID=$1; PROMPT=$2; name=$(echo "$ID" | tr A-Z a-z)
pane=$(herdr tab create --workspace ${WS:-w2} --cwd ~/dev/ssx3 --label "$ID" | python3 -c 'import json,sys;print(json.load(sys.stdin)["result"]["root_pane"]["pane_id"])')
sleep 4; herdr agent start "$name" --kind codex --pane "$pane" --timeout 120000 -- -m gpt-6-sol --approve-for-me -c sandbox_workspace_write.network_access=true --add-dir ~/dev/ssx3-work --add-dir ~/dev/PS2Recomp --add-dir /tmp >/dev/null || { echo "$ID start failed"; exit 1; }; sleep 10
herdr agent prompt "$name" "$PROMPT Commit trailer for this brief: 'Orchestrated-By: Codex'. You are a worker on a brief: follow ~/dev/AGENTS.md worker rules (touch only what the brief allows; on a denial or first failure, stop and report). Write scope: the brief is your authorization for the paths it names — ~/dev/ssx3 (report dir + commit), ~/dev/ssx3-work dirs it names, local worktrees/branches of ~/dev/PS2Recomp it names (no push), and the lease files via local/tooling/p_lane_lease.py count as inside your started folder; all else read-only. Stop rule: \"first failure\" means a failed BRIEF STEP (build after one fix attempt, test/gate, boot crash, lease, denied permission), not your own exploratory command errors (wrong path, typo) — fix those and keep going. Fork paths in briefs are relative to the fork worktree." --wait --until working --timeout 30000 | python3 -c 'import json,sys;r=json.load(sys.stdin)["result"]["agent"];print(r["name"],r["pane_id"],r["agent_status"])'
